<style>
:root{--bg:#f7f8fd;--card:#fff;--tx:#161a3a;--mu:#646a90;--bd:#e5e8f4;--pr:#4f46e5;--pr2:#7c3aed;--ok:#10b981;--pk:#d946ef;--cy:#06b6d4;--am:#f59e0b;--inb:#e0e7ff;--sh:0 8px 30px rgba(50,50,120,.08);--tr:#f1f5f9;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px)}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]){--bg:#0e1125;--card:#171b35;--tx:#eceefc;--mu:#9aa0c7;--bd:#272c52;--inb:#262a63;--sh:none;--tr:#20244a}}
:root[data-theme="dark"]{--bg:#0e1125;--card:#171b35;--tx:#eceefc;--mu:#9aa0c7;--bd:#272c52;--inb:#262a63;--sh:none;--tr:#20244a}
*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:calc(env(safe-area-inset-top,0px) + 70px)}
body{margin:0;background:var(--bg);color:var(--tx);font-family:"Hind Siliguri","Noto Sans Bengali",system-ui,sans-serif;line-height:1.6;overflow-x:hidden}
a{color:inherit;text-decoration:none}.w{max-width:1120px;margin:0 auto;padding:0 18px}
header{position:sticky;top:env(safe-area-inset-top,0px);z-index:30;background:color-mix(in srgb,var(--card) 90%,transparent);backdrop-filter:blur(10px);border-bottom:1px solid var(--bd)}
.hd{display:flex;align-items:center;gap:14px;height:62px}.logo{display:flex;align-items:center;gap:9px;font-weight:700;font-size:19px}
.logo i{width:36px;height:36px;border-radius:11px;background:linear-gradient(135deg,var(--pr),var(--pr2));display:grid;place-items:center;font-style:normal}
.logo-img{height:38px;display:block}
.logo-dark{display:none}
.logo-light{display:block}
:root[data-theme="dark"] .logo-dark{display:block}
:root[data-theme="dark"] .logo-light{display:none}
:root[data-theme="light"] .logo-dark{display:none}
:root[data-theme="light"] .logo-light{display:block}
@media(prefers-color-scheme:dark){:root:not([data-theme="light"]):not([data-theme="dark"]) .logo-dark{display:block}:root:not([data-theme="light"]):not([data-theme="dark"]) .logo-light{display:none}}
@media(prefers-color-scheme:light){:root:not([data-theme="light"]):not([data-theme="dark"]) .logo-dark{display:none}:root:not([data-theme="light"]):not([data-theme="dark"]) .logo-light{display:block}}
nav{display:none;gap:22px;margin-left:24px;color:var(--mu);font-weight:600}nav a:hover{color:var(--pr)}.sp{flex:1}
.btn{display:inline-flex;align-items:center;gap:8px;border:0;border-radius:13px;padding:11px 22px;font:inherit;font-weight:700;cursor:pointer;color:#fff;background:linear-gradient(135deg,var(--pr),var(--pr2) 50%,var(--pk));box-shadow:0 0 28px rgba(99,102,241,.35);transition:.3s}
.btn:hover{transform:translateY(-3px);box-shadow:0 0 44px rgba(99,102,241,.55)}.btn.o{background:var(--card);color:var(--pr);border:1px solid var(--bd);box-shadow:none}
.ib{border:1px solid var(--bd);background:var(--card);color:var(--tx);border-radius:10px;padding:8px 11px;cursor:pointer}
/* reveal */
.rv{opacity:0;transform:translateY(30px);transition:opacity .7s ease,transform .7s ease;transition-delay:var(--d,0s)}.rv.in{opacity:1;transform:none}
/* hero */
.hero{position:relative;overflow:hidden;padding:64px 0 90px;background:radial-gradient(ellipse 80% 60% at 70% 20%,rgba(99,102,241,.14),transparent),radial-gradient(ellipse 60% 50% at 20% 80%,rgba(139,92,246,.12),transparent)}
.orb{position:absolute;border-radius:50%;filter:blur(80px);opacity:.25;animation:orb 8s ease-in-out infinite alternate}
.o1{width:380px;height:380px;top:-100px;right:-40px;background:linear-gradient(135deg,#6366f1,#8b5cf6)}.o2{width:280px;height:280px;bottom:-80px;left:8%;background:linear-gradient(135deg,var(--pk),#ec4899);animation-delay:2s}.o3{width:230px;height:230px;top:40%;left:58%;background:linear-gradient(135deg,var(--cy),#0ea5e9);animation-delay:4s;opacity:.16}
@keyframes orb{to{transform:translate(30px,-30px) scale(1.1)}}
#pt{position:absolute;inset:0;pointer-events:none}.pt{position:absolute;bottom:-10px;border-radius:50%;background:rgba(99,102,241,.45);animation:up linear infinite}
@keyframes up{0%{transform:translateY(0) scale(0);opacity:0}10%{opacity:1}90%{opacity:1}100%{transform:translateY(-105vh) scale(1);opacity:0}}
.hero .w{position:relative;z-index:2;display:grid;gap:34px;align-items:center}
.bdg{display:inline-flex;align-items:center;gap:8px;padding:6px 14px;border:1px solid rgba(99,102,241,.25);border-radius:99px;background:var(--card);color:var(--pr);font-size:13px;font-weight:700;animation:fu .8s both}
.bdg b{width:8px;height:8px;border-radius:50%;background:linear-gradient(135deg,var(--pr),var(--pk));animation:pl 2s infinite}
@keyframes pl{50%{opacity:.5;transform:scale(1.4)}}@keyframes fu{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:none}}@keyframes ri{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}
h1{font-size:clamp(32px,6vw,54px);line-height:1.15;margin:14px 0;letter-spacing:-.03em;animation:fu .8s .2s both}h1 span,.gt{background:linear-gradient(135deg,var(--pr),var(--pr2),var(--pk));-webkit-background-clip:text;background-clip:text;color:transparent}
.lead{color:var(--mu);font-size:17px;max-width:520px;animation:fu .8s .4s both}.cta{display:flex;gap:12px;flex-wrap:wrap;margin-top:22px;animation:fu .8s .6s both}
.hm{background:var(--card);border:1px solid var(--bd);border-radius:20px;padding:16px;box-shadow:var(--sh);animation:fu .9s .5s both,fl 6s 1.5s ease-in-out infinite}
@keyframes fl{50%{transform:translateY(-12px)}}
.hm .r{display:flex;align-items:center;gap:10px;padding:9px 0;border-top:1px solid var(--bd);font-size:14px;opacity:0;animation:ri .6s ease forwards}.hm .r:nth-child(2){animation-delay:1s}.hm .r:nth-child(3){animation-delay:1.3s}.hm .r:nth-child(4){animation-delay:1.6s}
.av{width:30px;height:30px;border-radius:50%;background:var(--inb);color:var(--pr);display:grid;place-items:center;font-weight:700;font-size:13px}.r span:nth-child(2){flex:1}
.b{padding:2px 10px;border-radius:99px;font-size:12px;font-weight:700;color:#fff}.bp{background:var(--ok)}.bl{background:var(--am)}.ba{background:#ef4444}
/* stats */
.stats{position:relative;z-index:3;margin-top:-50px;display:grid;grid-template-columns:repeat(2,1fr);gap:12px}
.st{background:var(--card);border:1px solid var(--bd);border-radius:18px;padding:16px;text-align:center;box-shadow:var(--sh);transition:.3s}.st:hover{transform:translateY(-5px)}
.st i{width:44px;height:44px;border-radius:14px;display:grid;place-items:center;margin:0 auto 6px;font-style:normal;font-size:20px;color:#fff}.st b{font-size:28px;display:block}.st span{color:var(--mu);font-size:13px}
section{padding:60px 0}.hl{text-align:center;max-width:600px;margin:0 auto 32px}.tag{display:inline-block;background:var(--inb);color:var(--pr);padding:5px 14px;border-radius:99px;font-size:12px;font-weight:700;letter-spacing:.06em}.hl h2{font-size:clamp(25px,4.5vw,36px);margin:10px 0 6px;letter-spacing:-.03em}.hl p{color:var(--mu);margin:0}
/* bento */
.bo{display:grid;gap:14px}.bc{background:var(--card);border:1px solid var(--bd);border-radius:18px;padding:16px;box-shadow:var(--sh);display:flex;flex-direction:column;gap:6px;transition:.25s}.bc:hover{transform:translateY(-3px)}
.bc h3{margin:0;font-size:16px}.bc p{margin:0;font-size:13px;color:var(--mu)}.vz{position:relative;flex:1;min-height:236px;border-radius:14px;border:1px solid var(--bd);background:var(--bg);overflow:hidden;margin-top:6px}
.pipe{display:flex;align-items:center;justify-content:center}.pipe svg{position:absolute;inset:0;width:100%;height:100%}
.pipe .f path{stroke-dasharray:1;stroke-dashoffset:1;transition:stroke-dashoffset .8s}.pipe .f.on path{stroke-dashoffset:0}
.nd{position:absolute;transform:translate(-50%,-50%);transition:transform .3s}.nb{width:52px;height:52px;border-radius:14px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#fff;font-size:18px;line-height:1;box-shadow:0 6px 14px rgba(0,0,0,.18)}.nb small{font-size:9px;font-weight:700;margin-top:3px}
.rt{width:22px;height:22px;border-radius:50%;border:2px solid var(--tx);background:var(--card);display:grid;place-items:center}.rt i{width:11px;height:11px;border-radius:50%;border:1.5px dashed var(--tx);animation:sp 4s linear infinite}@keyframes sp{to{transform:rotate(360deg)}}
.nd.hot{transform:translate(-50%,-50%) scale(1.14)}
.bars{display:flex;align-items:flex-end;gap:8px;height:100%;padding:14px 12px 10px}.bar{flex:1;height:100%;display:flex;flex-direction:column;align-items:center;gap:4px;font-size:11px;color:var(--mu)}
.bt{flex:1;width:100%;background:var(--tr);border-radius:9px;display:flex;align-items:flex-end;overflow:hidden}.bf{width:100%;border-radius:8px 8px 3px 3px;background:linear-gradient(180deg,var(--pr2),var(--pr));animation:wv var(--du) ease-in-out var(--de) infinite}
@keyframes wv{0%,100%{height:var(--h)}25%{height:calc(var(--h) + 8%)}60%{height:calc(var(--h) - 10%)}}
.fd{position:absolute;left:14px;right:14px;top:50%;margin-top:-26px;display:flex;align-items:center;gap:10px;padding:9px 11px;border-radius:13px;background:var(--card);border:1px solid var(--bd);box-shadow:0 4px 14px rgba(9,9,11,.08);transition:transform .45s cubic-bezier(.34,1.56,.64,1),opacity .3s}
.fd .ck{width:30px;height:30px;border-radius:9px;color:#fff;display:grid;place-items:center;font-size:13px;flex-shrink:0}.fd b{font-size:13px;display:block}.fd small{color:var(--mu);font-size:11px}
.dp{display:flex;flex-direction:column;gap:10px;padding:14px}.dr{display:flex;align-items:center;gap:10px;font-size:13px}.dr em{font-style:normal;width:84px;color:var(--mu)}.dk{flex:1;height:8px;background:var(--tr);border-radius:9px;overflow:hidden}.dk i{display:block;height:100%;width:0;border-radius:9px;position:relative;overflow:hidden;transition:width 1.3s cubic-bezier(.22,1,.36,1)}
.dk i::after{content:"";position:absolute;inset:0;background:linear-gradient(90deg,transparent,rgba(255,255,255,.6),transparent);transform:translateX(-100%);animation:bm 1.6s linear infinite}@keyframes bm{to{transform:translateX(100%)}}
.live{font-size:11px;color:var(--mu);display:flex;align-items:center;gap:6px;margin-top:auto;padding:0 14px 12px}.live b{width:6px;height:6px;border-radius:50%;background:var(--ok);box-shadow:0 0 0 0 rgba(16,185,129,.5);animation:pg 2s infinite}@keyframes pg{to{box-shadow:0 0 0 8px rgba(16,185,129,0)}}
/* steps */
.sg{display:grid;gap:18px}.sc{background:var(--card);border:1px solid var(--bd);border-radius:26px;overflow:hidden;text-align:center;box-shadow:var(--sh);transition:.4s}.sc:hover{transform:translateY(-8px)}
.sm{height:230px;background:linear-gradient(180deg,var(--inb),var(--card));display:flex;justify-content:center;align-items:flex-end;padding-top:20px}
.ph{width:180px;height:210px;background:var(--card);border:4px solid #23192d;border-bottom:0;border-radius:28px 28px 0 0;padding:8px 10px;font-size:10px;text-align:left;transition:.4s;transform:translateY(2px)}.sc:hover .ph{transform:translateY(-6px)}
.ph .nt{width:40px;height:8px;background:#0f172a;border-radius:9px;margin:0 auto 8px}.ph div.l{background:var(--bg);border-radius:8px;padding:6px 8px;margin-bottom:5px;display:flex;justify-content:space-between}
.sx{padding:20px 18px 26px}.pill{display:inline-block;padding:2px 14px;border:1px solid var(--bd);border-radius:99px;font-size:12px;font-weight:600;color:var(--mu)}.sx h3{margin:10px 0 4px}.sx p{margin:0;color:var(--mu);font-size:14px}
/* coverflow */
.cf{position:relative;height:300px;perspective:1100px;max-width:900px;margin:0 auto}.cs{position:absolute;left:50%;top:6px;width:290px;margin-left:-145px;height:280px;background:var(--card);border:1.5px solid var(--bd);border-radius:20px;padding:20px;transition:transform .55s cubic-bezier(.16,1,.3,1),opacity .45s;cursor:pointer}
.cs.c{transform:translateZ(50px);opacity:1;z-index:5;box-shadow:0 20px 60px rgba(124,58,237,.2);border-color:var(--pr2)}.cs.l1{transform:translateX(-250px) translateZ(-60px) rotateY(32deg) scale(.86);opacity:.8;z-index:4}.cs.r1{transform:translateX(250px) translateZ(-60px) rotateY(-32deg) scale(.86);opacity:.8;z-index:4}.cs.h{transform:translateZ(-250px) scale(.4);opacity:0;pointer-events:none}
.cs .stt{color:#f59e0b;letter-spacing:2px}.cs p{font-size:15px;margin:10px 0}.cs small{color:var(--mu)}
.cn{display:flex;justify-content:center;align-items:center;gap:14px;margin-top:20px}.cn button{width:44px;height:44px;border-radius:50%;border:1.5px solid var(--bd);background:var(--card);color:var(--tx);cursor:pointer;font-size:16px}.dts{display:flex;gap:6px}.dts i{width:10px;height:10px;border-radius:50%;border:2px solid var(--bd);transition:.25s}.dts i.on{background:var(--pr);border-color:var(--pr);transform:scale(1.25)}
/* pricing faq cta */
.pg{display:grid;gap:16px}.pc{background:var(--card);border:1px solid var(--bd);border-radius:20px;padding:22px;box-shadow:var(--sh);transition:.3s}.pc:hover{transform:translateY(-6px)}.pc.f{border:2px solid var(--pr)}.pc b.p{font-size:34px;display:block;margin:6px 0}.pc ul{list-style:none;padding:0;margin:10px 0 16px;color:var(--mu);font-size:14px}.pc li::before{content:"✓ ";color:var(--ok);font-weight:700}
details{background:var(--card);border:1px solid var(--bd);border-radius:14px;padding:14px 18px;margin-bottom:10px}summary{cursor:pointer;font-weight:600}details p{color:var(--mu);margin:8px 0 0}
.dm{background:linear-gradient(135deg,var(--pr),var(--pr2));color:#fff;border-radius:24px;padding:30px 22px;display:grid;gap:20px}.dm h2{margin:0 0 8px}form{background:var(--card);color:var(--tx);border-radius:18px;padding:18px;display:grid;gap:10px}form input{width:100%;padding:11px 13px;border-radius:11px;border:1px solid var(--bd);background:var(--bg);color:var(--tx);font:inherit}#ok{display:none;color:var(--ok);font-weight:700}
footer{border-top:1px solid var(--bd);padding:24px 0;color:var(--mu);font-size:14px;text-align:center}
@media(min-width:800px){nav{display:flex}.hero .w{grid-template-columns:1.05fr 1fr}.stats{grid-template-columns:repeat(4,1fr)}.bo{grid-template-columns:repeat(3,1fr)}.sp2{grid-column:span 2}.sg,.pg{grid-template-columns:repeat(3,1fr)}.dm{grid-template-columns:1fr 1fr;padding:44px}}
@media(max-width:600px){.cs.l1{transform:translateX(-170px) translateZ(-60px) rotateY(26deg) scale(.78);opacity:.5}.cs.r1{transform:translateX(170px) translateZ(-60px) rotateY(-26deg) scale(.78);opacity:.5}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;transition:none!important}.rv,.hm .r{opacity:1;transform:none}}
</style>
