<script>
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],RM=matchMedia('(prefers-reduced-motion:reduce)').matches;
const bn=n=>String(n).replace(/\d/g,d=>"০১২৩৪৫৬৭৮৯"[d]);
/* particles */
if(!RM)for(let i=0;i<34;i++){const p=document.createElement('span');p.className='pt';const s=2+Math.random()*4;p.style.cssText=`left:${Math.random()*100}%;width:${s}px;height:${s}px;animation-duration:${6+Math.random()*8}s;animation-delay:${Math.random()*8}s`;$('#pt').appendChild(p)}
/* reveal + counters */
const io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;e.target.classList.add('in');const c=e.target.querySelector('[data-n]');if(c)count(c);io.unobserve(e.target)}),{threshold:.15});$$('.rv').forEach(e=>io.observe(e));
function count(el){const t=+el.dataset.n,st=performance.now();(function f(n){const k=Math.min((n-st)/1400,1),v=Math.round(t*(1-Math.pow(1-k,3)));el.textContent=bn(v.toLocaleString('en-US'))+(t>=500&&t!==80?'+':'');if(k<1&&!RM)requestAnimationFrame(f)})(st);if(RM)el.textContent=bn(t.toLocaleString('en-US'))}
/* pipeline */
const pp=$('#pipe'),fl=$$('#pipe .f'),nds=$$('#pipe .nd');let ps=0;
function pstep(){fl.forEach(g=>g.classList.toggle('on',+g.dataset.s===ps));nds.forEach(n=>n.classList.toggle('hot',+n.dataset.s===ps||+n.dataset.s===ps-1&&ps>0&&ps<5))}
pstep();if(!RM)setInterval(()=>{ps=(ps+1)%6;pstep()},1800);
/* bars */
$('#bars').innerHTML=[["শনি",92],["রবি",88],["সোম",95],["মঙ্গল",90],["বুধ",78],["বৃহ",93],["আজ",96]].map((d,i)=>`<div class="bar"><div class="bt"><span class="bf" style="--h:${d[1]-30}%;--du:${2.6+i%3*.7}s;--de:${i*.1}s"></span></div>${d[0]}<b>${bn(d[1])}%</b></div>`).join('');
/* feed */
const F=[["রাকিবুল হাসান","চেক-ইন ৯:০২","#10b981","✔"],["তানভীর আহমেদ","দেরিতে ৯:৪০","#f59e0b","⏰"],["সাদিয়া ইসলাম","চেক-ইন ৮:৫৫","#10b981","✔"],["নুসরাত জাহান","অনুপস্থিত","#ef4444","✖"],["মেহেদী হাসান","চেক-আউট ৬:১০","#6366f1","↪"],["লামিয়া লোভা","চেক-ইন ৮:৪৮","#10b981","✔"]];
$('#feed').innerHTML=F.map(f=>`<div class="fd"><span class="ck" style="background:${f[2]}">${f[3]}</span><div><b>${f[0]}</b><small>${f[1]}</small></div></div>`).join('');
const fd=$$('.fd'),Y={0:0,1:60,2:105,"-1":-60,"-2":-105};let fi=0;
function fplace(){fd.forEach((e,i)=>{let r=i-fi;const N=fd.length;if(r>N/2)r-=N;if(r<-N/2)r+=N;const a=Math.abs(r),v=a<=2;e.style.transform=`translateY(${v?Y[r]:r<0?-160:160}px) scale(${a==0?1:a==1?.93:.87})`;e.style.opacity=v?(a==0?1:a==1?.65:.35):0;e.style.zIndex=10-a})}
fplace();if(!RM)setInterval(()=>{fi=(fi+1)%fd.length;fplace()},2300);
/* dept bars */
const D=[["প্রোডাকশন",100,"#6366f1,#60a5fa","৳১২.৪ লাখ"],["সেলস",72,"#8b5cf6,#a78bfa","৳৮.৯ লাখ"],["অ্যাকাউন্টস",48,"#d946ef,#f472b6","৳৫.৯ লাখ"],["এইচআর",30,"#14b8a6,#5eead4","৳৩.৭ লাখ"],["আইটি",56,"#f59e0b,#fbbf24","৳৬.৯ লাখ"]];
$('#dp').innerHTML=D.map(d=>`<div class="dr"><em>${d[0]}</em><div class="dk"><i data-w="${d[1]}" style="background:linear-gradient(90deg,${d[2]})"></i></div><b style="font-size:12px;width:70px;text-align:right">${d[3]}</b></div>`).join('');
const dio=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){$$('.dk i').forEach(i=>i.style.width=i.dataset.w+'%');dio.disconnect()}}),{threshold:.3});dio.observe($('#dp'));
$('#mini').innerHTML=[["উপস্থিত","৮৬","#10b981"],["দেরি","৭","#f59e0b"],["অনুপস্থিত","৫","#ef4444"],["ছুটি","৪","#6366f1"]].map(m=>`<div class="dr"><em>${m[0]}</em><div class="dk"><i data-w="${parseInt(m[1])}" style="background:${m[2]}"></i></div><b>${m[1]}</b></div>`).join('');
/* coverflow */
const T=[["আরিফ রহমান","এমডি, রহমান গার্মেন্টস","আগে মাসের ৫ দিন লাগত বেতন হিসাবে। এখন ৫ মিনিটে পে-স্লিপসহ সব রেডি।"],["সুমাইয়া আক্তার","এইচআর, টেকনোভা","অ্যাপ চেক-ইনে দেরি অনেক কমেছে। সাপোর্ট টিম বাংলায় কথা বলে।"],["মাসুদ করিম","মালিক, করিম সুপারশপ","তিন শাখার হাজিরা এক স্ক্রিনে দেখি। ভীষণ সুবিধা।"],["নাদিয়া সুলতানা","অ্যাডমিন, গ্রিন ফ্যাশন","ওভারটাইম হিসাব এখন নির্ভুল, কর্মীদের অভিযোগ প্রায় শূন্য।"],["ফাহিম হাসান","সিইও, স্মার্ট আইটি","সেটআপ ১ দিনেই হয়ে গেছে। দাম অনুযায়ী দারুণ।"]];
$('#cf').innerHTML=T.map((t,i)=>`<div class="cs" data-i="${i}"><div class="stt">★★★★★</div><p>${t[2]}</p><b>${t[0]}</b><br><small>${t[1]}</small></div>`).join('');
$('#dts').innerHTML=T.map(()=>'<i></i>').join('');
const cs=$$('.cs'),dt=$$('#dts i');let ci=0,at;
function cpos(){cs.forEach((s,i)=>{let d=(i-ci)%5;if(d<-2)d+=5;if(d>2)d-=5;s.className='cs '+(d==0?'c':d==-1?'l1':d==1?'r1':'h')});dt.forEach((d,i)=>d.classList.toggle('on',i===ci))}
function go(n){ci=(n+5)%5;cpos()}function auto(){clearInterval(at);if(!RM)at=setInterval(()=>go(ci+1),4000)}
$('#pv').onclick=()=>{go(ci-1);auto()};$('#nx').onclick=()=>{go(ci+1);auto()};cs.forEach((s,i)=>s.onclick=()=>{go(i);auto()});cpos();auto();
$$('a[href^="#"]').forEach(a=>a.addEventListener('click',()=>setTimeout(()=>{const t=$(a.getAttribute('href'));t&&t.querySelectorAll('.rv').forEach(e=>{e.classList.add('in');const c=e.querySelector('[data-n]');if(c)count(c)})},600)));
/* misc */
$('#fm').onsubmit=e=>{e.preventDefault();$('#ok').style.display='block';e.target.reset()};
$('#th').onclick=()=>{const r=document.documentElement,d=r.dataset.theme==='dark'||(!r.dataset.theme&&matchMedia('(prefers-color-scheme:dark)').matches);r.dataset.theme=d?'light':'dark'};
</script>
<script>(function(){var b=document.getElementById('mt'),n=document.querySelector('header nav');if(!b||!n)return;
function s(o){n.classList.toggle('open',o);b.textContent=o?'✕':'☰';b.setAttribute('aria-expanded',o)}
b.addEventListener('click',function(){s(!n.classList.contains('open'))});
n.addEventListener('click',function(e){if(e.target.tagName==='A')s(false)});
document.addEventListener('keydown',function(e){if(e.key==='Escape')s(false)});
window.addEventListener('resize',function(){if(innerWidth>=800)s(false)});})();</script>
</body>
